content.solution_code:
class MysticalArtifact {
    constructor(name) {
        this.name = name;
        this.attunedTo = null;
    }

    attune(user) {
        this.attunedTo = user;
        return `${this.name} is now attuned to ${user}.`;
    }

    activate() {
        throw new Error("Abstract method 'activate' must be implemented by subclasses.");
    }
}

class AmuletOfShielding extends MysticalArtifact {
    constructor(name) {
        super(name);
    }

    activate() {
        if (this.attunedTo) {
            return `${this.name} emits a protective barrier for ${this.attunedTo}!`;
        } else {
            return `${this.name} is not attuned!`;
        }
    }
}

class WandOfBlasting extends MysticalArtifact {
    constructor(name) {
        super(name);
    }

    activate() {
        if (this.attunedTo) {
            return `${this.name} unleashes a powerful blast for ${this.attunedTo}!`;
        } else {
            return `${this.name} is not attuned!`;
        }
    }
}

